void can_per_tx( Boolean execute , Can_Per_Obj *can_per_obj )
{
    Can_Msg       can_msg ; 
    Can_Per_Flags flags ; 

    if( !execute ) return ;
    
    if( can_per_obj->can_per_func )
    {
        flags = (can_per_obj->can_per_func)( &can_msg , can_per_obj->can_per_arg ) ;
        
        if( flags&CAN_PER_COMPLETE )    can_per_obj->req_done = TRUE ;                  
        
        if( flags&CAN_PER_DEV0     )
        {
            can_per_do_tx( CAN_DEV_0 , &can_msg ); 
        }
        
        if( flags&CAN_PER_DEV1     )
        {
            can_per_do_tx( CAN_DEV_1 , &can_msg ); 
        }
    }
}

